<script lang="ts">
    import SvgIcons from "$lib/components/SvgIcons.svelte";
    import NotoEmoji from "$lib/components/NotoEmoji.svelte";
    import type { IMenuItem } from "./FlexibleMenu.types";
    import { logService } from "$lib/services/logService.svelte";
    import { customTooltip } from "$lib/actions/customTooltip";

    interface Props {
        item: IMenuItem;
        dataTestId?: string;
    }

    let { item, dataTestId = "" }: Props = $props();

    function handleClick(e: MouseEvent) {
        logService.action(`[MenuButton] Clicked: id=${item.id}, dataTestId=${dataTestId}`);
        if (item.onClick) {
            item.onClick(e);
        } else {
            logService.error(`[MenuButton] No onClick handler for item: ${item.id}`);
        }
    }
</script>

<button
    class="menu-button {item.isActive ? 'active' : ''} {item.primary
        ? 'primary'
        : ''}"
    onclick={handleClick}
    aria-label={item.label || item.id}
    type="button"
    data-testid={dataTestId}
    use:customTooltip={item.tooltip || item.label}
>
    <div class="icon-wrapper">
        {#if item.snippet}
            {@render item.snippet()}
        {:else if item.icon}
            <SvgIcons name={item.icon} />
        {:else if item.emoji}
            <!-- FIX: Прибрано хардкод перевірки на конкретні емодзі. 
                 Тепер компонент очікує валідну назву для NotoEmoji. -->
            <NotoEmoji name={item.emoji} size="1em" />
        {/if}
    </div>
</button>

